package com.hrms.employee.entity;

import com.hrms.common.audit.Auditable;
import com.hrms.common.enums.Gender;
import com.hrms.common.util.BooleanToNumberConverter;
import jakarta.persistence.*;
import lombok.*;

import java.time.LocalDate;

/**
 * Experience record of an employee (table EMPLOYEE_EXPERIENCE, created by V5). Never deleted, only deactivated.
 * Generated by tools/generate_employee_info.py.
 */
@Entity
@Table(name = "EMPLOYEE_EXPERIENCE", schema = "HRMS")
@Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class EmployeeExperience extends Auditable {

    @Id
    @GeneratedValue(strategy = GenerationType.SEQUENCE, generator = "employee_experience_seq")
    @SequenceGenerator(name = "employee_experience_seq", sequenceName = "HRMS.SEQ_EMPLOYEE_EXPERIENCE", allocationSize = 1)
    @Column(name = "EXPERIENCE_ID", nullable = false)
    private Long id;

    @Column(name = "EMPLOYEE_ID", nullable = false)
    private Long employeeId;

    @Column(name = "EMPLOYER_NAME", nullable = false, length = 200)
    private String employerName;

    @Column(name = "EMPLOYER_NAME_AR", columnDefinition = "NVARCHAR2(200)")
    private String employerNameAr;

    @Column(name = "JOB_TITLE", length = 100)
    private String jobTitle;

    @Column(name = "PLACE", length = 100)
    private String place;

    @Column(name = "START_DATE")
    private LocalDate startDate;

    @Column(name = "END_DATE")
    private LocalDate endDate;

    @Convert(converter = BooleanToNumberConverter.class)
    @Column(name = "IS_ACTIVE", nullable = false)
    private Boolean isActive;

    /** Optimistic lock: a stale writer gets HTTP 409. */
    @Version
    @Column(name = "VERSION", nullable = false)
    private Long version;
}
